const OBLI_X = "I bear witness, O my God, that Thou hast created me to know Thee\nand to worship Thee.\nI testify, at this moment, to my powerlessness and to Thy might, to my poverty and to Thy wealth.\n\nThere is none other God but Thee, the Help in Peril, the Self-Subsisting.";

const GENE_T = "O Thou Whose face is the object...\x01O Thou kind Lord!\x01O Lord, my God! This is a child...\x01Prayer for the Dead\x01Suffer me, O my God...\x01Glory to Thee, O my God!\x01O God, my Master, the Goal of my desire!\x01Glory be unto Thee, O Lord my God!\x01Glory be to Thee, O King of eternity...\x01Glorified art Thou, O Lord my God! I beseech \x01O God, my God!\x01Glorified art Thou, O Lord my God!\x01He is God! Thou seest us, O my God...\x01O God my God! I beg of Thee...\x01My God, Whom I worship and adore!\x01Thy unity is inscrutable, O my God...\x01He is the Bestower, the Bounteous!\x01O my God and my Master!\x01Glory be to Thee, O my God!\x01Unto Thee be praise, O Lord my God!\x01All praise, O my God, be to Thee...\x01Lauded be Thy name, O my God! Thou beholdest \x01Praise be to Thee, O Lord my God!\x01Magnified be Thy name, O God...\x01O God, and the God of all Names...\x01From the sweet-scented streams...\x01I magnify Thy Name, O my God...\x01Magnified be Thy name...\x01O Thou incomparable God!\x01O Thou Whose tests are a healing medicine...\x01Praise be to Thee, O Lord my God!\x01Thou seest, O my God...\x01O my God! O my God! Unite the hearts...\x01O Thou Whose face is the object...\x01O Thou kind Lord! From the horizon...";
const GENE_A = "Bahá'u'lláh\x01'Abdu’l-Bahá\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01The Báb\x01Bahá'u'lláh\x01Bahá'u'lláh\x01'Abdu’l-Bahá\x01Bahá'u'lláh\x01'Abdu’l-Bahá\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01'Abdu’l-Bahá\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01'Abdu’l-Bahá";
const GENE_X = "O Thou Whose face is the object of my adoration, Whose beauty is my sanctuary,\nWhose habitation is my goal, Whose praise is my hope, Whose providence is my companion, Whose love is the cause of my being,\nWhose mention is my solace, Whose nearness is my desire, Whose presence is my dearest wish and highest aspiration,\nI entreat Thee not to withhold from me the things Thou didst ordain for the chosen ones among Thy servants.\nSupply me, then, with the good of this world and of the next.\n\nThou, truly, art the King of all men.\nThere is no God but Thee, the Ever-Forgiving, the Most Generous.\x02Prayer for America\n\nO Thou kind Lord!\nThis gathering is turning to Thee.\nThese hearts are radiant with Thy love.\nThese minds and spirits are exhilarated by the message of Thy glad-tidings.\nO God!\nLet this American democracy become glorious in spiritual degrees even as it has aspired to material degrees,\nand render this just government victorious.\nConfirm this revered nation to upraise the standard of the oneness of humanity, to promulgate the Most Great Peace,\nto become thereby most glorious and praiseworthy among all the nations of the world.\nO God!\nThis American nation is worthy of Thy favors and is deserving of Thy mercy.\nMake it precious and near to Thee through Thy bounty and bestowal.\x02O\nLord, my God!\nThis is a child that hath sprung from the loins of one of Thy servants to whom Thou hast granted\na distinguished station in the Tablets of Thine irrevocable decree in the Books of Thy behest.\n\nI beseech Thee by Thy name, whereby everyone is enabled to attain the object of his desire, to\ngrant that this child may become a more mature soul amongst Thy servants; cause him to shine forth\nthrough the power of Thy name, enable him to utter Thy praise, to set his face towards Thee and to\ndraw nigh unto Thee.\nVerily it is Thou Who hast, from everlasting, been powerful to do as Thou willest and Who wilt,\nto eternity, remain potent to do as Thou pleasest.\nThere is none other God but Thee, the Exalted, the August, the Subduer, the Mighty, the All-Compelling.\x02O\nmy God!\nThis is Thy servant and the son of Thy servant who hath believed in Thee and in Thy signs, and set his face towards Thee,\nwholly detached from all except Thee.\nThou art, verily, of those who show mercy the most merciful.\n\nDeal with him, O Thou Who forgivest the sins of men and concealest their faults,\nas beseemeth the heaven of Thy bounty and the ocean of Thy grace.\nGrant him admission within the precincts of Thy transcendent mercy that was before the foundation of earth and heaven.\nThere is no God but Thee, the Ever-Forgiving, the Most Generous.\n\nLet him, then, repeat six times the greeting “Alláh-u-Abhá,”\nand then repeat nineteen times each of the following verses:\n\nWe all, verily, worship God.\n\nWe all, verily, bow down before God.\n\nWe all, verily, are devoted unto God.\n\nWe all, verily, give praise unto God.\n\nWe all, verily, yield thanks unto God.\n\nWe all, verily, are patient in God.\n\n(If the dead be a woman, let him say: This is Thy handmaiden and the daughter of Thy handmaiden, etc...)\x02Suffer me, O my God, to draw nigh unto Thee,\nand to abide within the precincts of Thy court, for remoteness from Thee hath well-nigh consumed me.\nCause me to rest under the shadow of the wings of Thy grace, for the flame of my separation from Thee hath melted my heart within me.\nDraw me nearer unto the river that is life indeed, for my soul burneth with thirst in its ceaseless search after Thee.\nMy sighs, O my God, proclaim the bitterness of mine anguish, and the tears I shed attest my love for Thee.\n\nI beseech Thee, by the praise wherewith Thou praisest Thyself and the glory wherewith Thou glorifiest Thine own Essence,\nto grant that we may be numbered among them that have recognized Thee and acknowledged Thy sovereignty in Thy days.\nHelp us then to quaff, O my God, from the fingers of mercy the living waters of Thy loving-kindness,\nthat we may utterly forget all else except Thee, and be occupied only with Thy Self.\nPowerful art Thou to do what Thou willest.\nNo God is there beside Thee, the Mighty, the Help in Peril, the Self-Subsisting.\n\nGlorified be Thy name, O Thou Who art the King of all Kings!\x02Glory to Thee, O my God!\nThe first stirrings of the spring of Thy grace have appeared and clothed Thine earth with verdure.\nThe clouds of the heaven of Thy bounty have rained their rain on this City within whose walls is imprisoned\nHim Whose desire is the salvation of Thy creatures.\nThrough it the soil of this City hath been decked forth, and its trees clothed with foliage, and its inhabitants gladdened.\n\nThe hearts of Thy dear ones, however, will rejoice only at the Divine Springtime of Thy tender mercies,\nwhereby the hearts are quickened, and the souls are renewed, and the trees of human existence bear their fruits.\n\nThe plants that have sprung forth, O my Lord, in the hearts of Thy loved ones have withered away.\nSend down upon them, from the clouds of Thy spirit, that which will cause the tender herbs of Thy knowledge and\nwisdom to grow within their breasts.\nRejoice, then, their hearts with the proclamation of Thy Cause and the exaltation of Thy sovereignty.\n\nTheir eyes, O my Lord, are expectantly turned in the direction of Thy bounty, and their faces are set towards the horizon of Thy grace.\nSuffer them not, through Thy bounty, to be deprived of Thy grace.\nPotent art Thou, by Thy sovereign might, over all things.\nNo God is there but Thee, the Almighty, the Help in Peril, the Self-Subsisting.\x02O\nmy God, my Master, the Goal of my desire!\nThis, Thy servant, seeketh to sleep in the shelter of Thy mercy, and to repose beneath the canopy of Thy grace,\nimploring Thy care and Thy protection.\n\nI beg of Thee, O my Lord, by Thine eye that sleepeth not, to guard mine eyes from beholding aught beside Thee.\nStrengthen, then, their vision that they may discern Thy signs, and behold the Horizon of Thy Revelation.\nThou art He before the revelations of Whose omnipotence the quintessence of power hath trembled.\n\nNo God is there but Thee, the Almighty, the All-Subduing, the Unconditioned.\x02Glory be unto Thee, O Lord my God!\nI beg Thee to forgive me and those who support Thy Faith.\nVerily, Thou art the sovereign Lord, the Forgiver, the Most Generous.\nO my God!\nEnable such servants of Thine as are deprived of knowledge to be admitted into Thy Cause; for once they learn of Thee,\nthey bear witness to the truth of the Day of Judgment and do not dispute the revelations of Thy bounty.\nSend down upon them the tokens of Thy grace, and grant them, wherever they reside,\na liberal share of that which Thou hast ordained for the pious among Thy servants.\nThou art in truth the Supreme Ruler, the All-Bounteous, the Most Benevolent.\n\nO my God!\nLet the outpourings of Thy bounty and blessings descend upon homes whose inmates have embraced Thy Faith,\nas a token of Thy grace and as a mark of loving-kindness from Thy presence.\nVerily, unsurpassed art Thou in granting forgiveness.\nShould Thy bounty be withheld from anyone, how could he be reckoned among the followers of the Faith in Thy Day?\n\nBless me, O my God, and those who will believe in Thy signs on the appointed Day, and such as cherish my love in their\nhearts—a love which Thou dost instill into them.\nVerily, Thou art the Lord of righteousness, the Most Exalted.\x02Glory be to Thee, O King of eternity, and the Maker of nations,\nand the Fashioner of every moldering bone!\nI pray Thee, by Thy Name through which Thou didst call all mankind unto the horizon of Thy majesty and glory,\nand didst guide Thy servants to the court of Thy grace and favors, to number me with such as have rid themselves from everything except Thyself,\nand have set themselves towards Thee, and have not been kept back by such misfortunes as were decreed by Thee,\nfrom turning in the direction of Thy gifts.\n\nI have laid hold, O my Lord, on the handle of Thy bounty, and clung steadfastly to the hem of the robe of Thy favor.\nSend down, then, upon me, out of the clouds of Thy generosity, what will purge out from me the remembrance of anyone except Thee,\nand make me able to turn unto Him Who is the Object of the adoration of all mankind, against Whom have been arrayed the stirrers of sedition,\nwho have broken Thy covenant, and disbelieved in Thee and in Thy signs.\n\nDeny me not, O my Lord, the fragrances of Thy raiment in Thy days, and deprive me not of the breathings of Thy Revelation at the\nappearance of the splendors of the light of Thy face.\nPowerful art Thou to do what pleaseth Thee.\nNaught can resist Thy will, nor frustrate what Thou hast purposed by Thy power.\n\nNo God is there but Thee, the Almighty, the All-Wise.\x02Glorified art Thou, O Lord my God! I beseech Thee by Thy Chosen Ones,\nand by the Bearers of Thy Trust, and by Him Whom Thou hast ordained to be the Seal of Thy Prophets and of Thy Messengers,\nto let Thy remembrance be my companion, and Thy love my aim, and Thy face my goal, and Thy name my lamp, and Thy wish my desire,\nand Thy pleasure my delight.\n\nI am a sinner, O my Lord, and Thou art the Ever-Forgiving.\nAs soon as I recognized Thee, I hastened to attain the exalted court of Thy loving-kindness.\nForgive me, O my Lord, my sins which have hindered me from walking in the ways of Thy good pleasure,\nand from attaining the shores of the ocean of Thy oneness.\n\nThere is no one, O my Lord, who can deal bountifully with me to whom I can turn my face,\nand none who can have compassion on me that I may crave his mercy.\nCast me not out, I implore Thee, of the presence of Thy grace, neither do Thou withhold from me the outpourings of Thy generosity and bounty.\nOrdain for me, O my Lord, what Thou hast ordained for them that love Thee, and write down for me what Thou hast written down for Thy chosen ones.\nMy gaze hath, at all times, been fixed on the horizon of Thy gracious providence, and mine eyes bent upon the court of Thy tender mercies.\nDo with me as beseemeth Thee.\nNo God is there but Thee, the God of power, the God of glory, Whose help is implored by all men.\x02All the friends of God... should contribute to the extent possible, however modest their offering may be.\nGod doth not burden a soul beyond its capacity.\nSuch contributions must come from all centers and all believers....\nO Friends of God!\nBe ye assured that in place of these contributions, your agriculture, your industry, and your commerce will be blessed by manifold increases,\nwith goodly gifts and bestowals.\nHe who cometh with one goodly deed will receive a tenfold reward.\nThere is no doubt that the living Lord will abundantly confirm those who expend their wealth in His path.\n\nO\nGod, my God!\nIllumine the brows of Thy true lovers, and support them with angelic hosts of certain triumph.\nSet firm their feet on Thy straight path, and out of Thine ancient bounty open before them the portals of Thy blessings;\nfor they are expending on Thy pathway what Thou hast bestowed upon them, safeguarding Thy Faith,\nputting their trust in their remembrance of Thee, offering up their hearts for love of Thee,\nand withholding not what they possess in adoration for Thy Beauty and in their search for ways to please Thee.\n\nO my Lord!\nOrdain for them a plenteous share, a destined recompense and sure reward.\n\nVerily, Thou art the Sustainer, the Helper, the Generous, the Bountiful, the Ever-Bestowing.\x02Glorified art Thou, O Lord my God!\nI implore Thee by the onrushing winds of Thy grace, and by them Who are the Daysprings of Thy purpose and the Dawning-Places of Thine inspiration,\nto send down upon me and upon all that have sought Thy face that which beseemeth Thy generosity and bountiful grace,\nand is worthy of Thy bestowals and favors.\nPoor and desolate I am, O my Lord!\nImmerse me in the ocean of Thy wealth; athirst, suffer me to drink from the living waters of Thy loving-kindness.\n\nI beseech Thee, by Thine own Self and by Him Whom Thou hast appointed as the Manifestation of Thine own Being and\nThy discriminating Word unto all that are in heaven and on earth, to gather together Thy servants beneath the shade of the\nTree of Thy gracious providence.\nHelp them, then, to partake of its fruits, to incline their ears to the rustling of its leaves,\nand to the sweetness of the voice of the Bird that chanteth upon its branches.\nThou art, verily, the Help in Peril, the Inaccessible, the Almighty, the Most Bountiful.\x02He is God!\nThou seest us, O my God, gathered around this table, praising Thy bounty, with our gaze set upon Thy Kingdom.\nO Lord!\nSend down upon us Thy heavenly food and confer upon us Thy blessing.\nThou art verily the Bestower, the Merciful, the Compassionate.\x02O\nGod my God!\nI beg of Thee by the ocean of Thy healing, and by the splendors of the Daystar of Thy grace,\nand by Thy Name through which Thou didst subdue Thy servants,\nand by the pervasive power of Thy most exalted Word and the potency of Thy most august Pen,\nand by Thy mercy that hath preceded the creation of all who are in heaven and on earth,\nto purge me with the waters of Thy bounty from every affliction and disorder, and from all weakness and feebleness.\n\nThou seest, O my Lord, Thy suppliant waiting at the door of Thy bounty,\nand him who hath set his hopes on Thee clinging to the cord of Thy generosity.\nDeny him not, I beseech Thee, the things he seeketh from the ocean of Thy grace and the Daystar of Thy loving-kindness.\n\nPowerful art Thou to do what pleaseth Thee.\nThere is none other God save Thee, the Ever-Forgiving, the Most Generous.\x02My God, Whom I worship and adore!\nI bear witness unto Thy unity and Thy oneness, and acknowledge Thy gifts, both in the past and in the present.\nThou art the All-Bountiful, the overflowing showers of Whose mercy have rained down upon high and low alike,\nand the splendors of Whose grace have been shed over both the obedient and the rebellious.\n\nO God of mercy, before Whose door the quintessence of mercy hath bowed down, and round the sanctuary of Whose Cause loving-kindness,\nin its inmost spirit, hath circled, we beseech Thee, entreating Thine ancient grace, and seeking Thy present favor,\nthat Thou mayest have mercy upon all who are the manifestations of the world of being,\nand deny them not the outpourings of Thy grace in Thy days.\n\nAll are but poor and needy, and Thou, verily, art the All-Possessing, the All-Subduing, the All-Powerful.\x02Thy unity is inscrutable, O my God,\nto all except them that have recognized Him Who is the Manifestation of Thy singleness and the Day-Spring of Thy oneness.\nWhoso assigneth a rival unto Him hath assigned a rival unto Thee, and whoso hath set up a peer for Him hath set up a peer for Thyself.\nNo, no, none can withstand Thee in the whole of creation.\nThou hast everlastingly been exalted far above all comparison and likeness.\nThy oneness hath been demonstrated by the oneness of Him Who is the Dawning-Place of Thy Revelation.\nWhosoever denieth this, hath denied Thy unity, and disputed with Thee about Thy sovereignty,\nand contended with Thee in Thy realm, and repudiated Thy commandments.\n\nAssist Thou Thy servants, O my Lord, to recognize Thy unity and to declare Thy oneness,\nthat all may gather together around what Thou didst desire in this Day whereon the sun of Thine essence hath shone forth above the horizon of Thy will,\nand the moon of Thine own being hath risen from the Day-Spring of Thy behest.\nThou art He, O my Lord, from Whose knowledge nothing whatsoever escapeth, and Whom no one can frustrate.\nThou doest Thy pleasure, by Thy sovereignty that overshadoweth the worlds.\n\nThou well knowest, O my God, my Best-Beloved, that naught can quench the thirst I suffer in my separation from Thee except the waters of Thy presence,\nand that the tumult of my heart can never be stilled save through the living fountain of my reunion with Thee.\nSend down, then, upon me, O my Lord, out of the heaven of Thy bounty what will draw me nearer unto the chalice of Thy gifts,\nand make me able to quaff the choice sealed Wine, Whose seal hath been loosed in Thy name,\nand from Which the sweet savors of Thy days have been shed abroad.\nThou, in truth, art the All-Bountiful, Whose grace is infinite.\n\nThe whole universe testifieth to Thy generosity.\nHave mercy, then, upon me by Thy graciousness, and deal bountifully with me through the power of Thy sovereignty,\nand suffer me to enjoy near access to Thee by Thy manifold favors.\nThou, truly, art the Great Giver, the Almighty, the Ever-Forgiving, the Most Bountiful.\x02The pledge of marriage, the verse to be spoken individually by the bride and the bridegroom in the presence\nof at least two witnesses acceptable to the Spiritual Assembly is, as stipulated in the Kitáb-i-Aqdas (The Most Holy Book):\n\n“We will, all, verily, abide by the Will of God.”\n\nHe is the Bestower, the Bounteous!\n\nPraise be to God, the Ancient, the Ever-Abiding, the Changeless, the Eternal!\nHe Who hath testified in His Own Being that verily He is the One, the Single, the Untrammelled, the Exalted.\nWe bear witness that verily there is no God but Him, acknowledging His oneness, confessing His singleness.\nHe hath ever dwelt in unapproachable heights, in the summits of His loftiness, sanctified from the mention of aught save Himself,\nfree from the description of aught but Him.\n\nAnd when He desired to manifest grace and beneficence to men, and to set the world in order,\nHe revealed observances and created laws; among them He established the law of marriage,\nmade it as a fortress for well-being and salvation,\nand enjoined it upon us in that which was sent down out of the heaven of sanctity in His Most Holy Book.\nHe saith, great is His glory: “Enter into wedlock, O people, that ye may bring forth one who will make mention of me amid My servants.\nThis is My bidding unto you; hold fast to it as an assistance to yourselves.”\x02O\nmy God and my Master!\nI am Thy servant and the son of Thy servant.\nI have risen from my couch at this dawntide when the Daystar of Thy oneness hath shone forth from the Dayspring of Thy will,\nand hath shed its radiance upon the whole world, according to what had been ordained in the Books of Thy Decree.\n\nPraise be unto Thee, O my God, that we have wakened to the splendors of the light of Thy knowledge.\nSend down, then, upon us, O my Lord, what will enable us to dispense with anyone but Thee,\nand will rid us of all attachment to aught except Thyself.\nWrite down, moreover, for me, and for such as are dear to me, and for my kindred, man and woman alike,\nthe good of this world and the world to come.\nKeep us safe, then, through Thine unfailing protection, O Thou the Beloved of the entire creation and the Desire of the whole universe,\nfrom them whom Thou hast made to be the manifestations of the Evil Whisperer, who whisper in men's breasts.\nPotent art Thou to do Thy pleasure.\nThou art, verily, the Almighty, the Help in Peril, the Self-Subsisting.\n\nBless Thou, O Lord my God, Him Whom Thou hast set over Thy most excellent Titles,\nand through Whom Thou hast divided between the godly and the wicked, and graciously aid us to do what Thou lovest and desirest.\nBless Thou, moreover, O my God, them Who are Thy Words and Thy Letters,\nand them who have set their faces towards Thee, and turned unto Thy face, and hearkened to Thy Call.\n\nThou art, truly, the Lord and King of all men, and art potent over all things.\x02Glory be to Thee, O my God!\nThou hearest Thine ardent lovers lamenting in their separation from Thee,\nand such as have recognized Thee wailing because of their remoteness from Thy presence.\nOpen Thou outwardly to their faces, O my Lord, the gates of Thy grace, that they may enter them by Thy leave and in conformity with Thy will,\nand may stand before the throne of Thy majesty,\nand catch the accents of Thy voice, and be illumined with the splendors of the light of Thy face.\n\nPotent art Thou to do what pleaseth Thee.\nNone can withstand the power of Thy sovereign might.\nFrom everlasting Thou wert alone, with none to equal Thee, and wilt unto everlasting remain far above all thought and every description of Thee.\nHave mercy, then, upon Thy servants by Thy grace and bounty, and suffer them not to be kept back from the shores of the ocean of Thy nearness.\nIf Thou abandonest them, who is there to befriend them; and if Thou puttest them far from Thee,\nwho is he that can favor them?\nThey have none other Lord beside Thee, none to adore except Thyself.\nDeal Thou generously with them by Thy bountiful grace.\n\nThou, in truth, art the Ever-Forgiving, the Most Compassionate.\x02Unto Thee be praise, O Lord my God!\nI entreat Thee, by Thy signs that have encompassed the entire creation,\nand by the light of Thy countenance that hath illuminated all that are in heaven and on earth,\nand by Thy mercy that hath surpassed all created things, and by Thy grace that hath suffused the whole universe,\nto rend asunder the veils that shut me out from Thee, that I may hasten unto the Fountain-Head of Thy mighty inspiration,\nand to the Day-Spring of Thy Revelation and bountiful favors, and may be immersed beneath the ocean of Thy nearness and pleasure.\n\nSuffer me not, O my Lord, to be deprived of the knowledge of Thee in Thy days, and divest me not of the robe of Thy guidance.\nGive me to drink of the river that is life indeed, whose waters have streamed forth from the Paradise (Ridván)\nin which the throne of Thy Name, the All-Merciful, was established, that mine eyes may be opened, and my face be illumined,\nand my heart be assured, and my soul be enlightened, and my steps be made firm.\n\nThou art He Who from everlasting was, through the potency of His might, supreme over all things, and,\nthrough the operation of His will, was able to ordain all things.\nNothing whatsoever, whether in Thy heaven or on Thy earth, can frustrate Thy purpose.\nHave mercy, then, upon me, O my Lord, through Thy gracious providence and generosity,\nand incline mine ear to the sweet melodies of the birds that warble their praise of Thee, amidst the branches of the tree of Thy oneness.\n\nThou art the Great Giver, the Ever-Forgiving, the Most Compassionate.\x02All praise, O my God, be to Thee Who art the Source of all glory and majesty,\nof greatness and honor, of sovereignty and dominion, of loftiness and grace, of awe and power.\nWhomsoever Thou willest Thou causest to draw nigh unto the Most Great Ocean,\nand on whomsoever Thou desirest Thou conferrest the honor of recognizing Thy Most Ancient Name.\nOf all who are in heaven and on earth, none can withstand the operation of Thy sovereign Will.\nFrom all eternity Thou didst rule the entire creation, and Thou wilt continue for evermore to exercise Thy dominion over all created things.\nThere is none other God but Thee, the Almighty, The Most Exalted, the All-Powerful, the All-Wise.\n\nIllumine, O Lord, the faces of Thy servants, that they may behold Thee;\nand cleanse their hearts that they may turn unto the court of Thy heavenly favors,\nand recognize Him Who is the Manifestation of Thy Self and the Dayspring of Thine Essence.\nVerily, Thou art the Lord of all worlds.\nThere is no God but Thee, the Unconstrained, the All-Subduing.\x02Lauded be Thy name, O my God!\nThou beholdest me in the clutches of my oppressors.\nEvery time I turn to my right, I hear the voice of the lamentation of them that are dear to Thee,\nwhom the infidels have made captives for having believed in Thee and in Thy signs,\nand for having set their faces towards the horizon of Thy grace and of Thy loving-kindness.\nAnd when I turn to my left, I hear the clamor of the wicked doers who have disbelieved in Thee and in Thy signs,\nand persistently striven to put out the light of Thy lamp which sheddeth the radiance of Thine own Self\nover all that are in Thy heaven and all that are on Thy earth.\n\nThe hearts of Thy chosen ones, O my Lord, have melted because of their separation from Thee,\nand the souls of Thy loved ones are burnt up by the fire of their yearning after Thee in Thy days.\nI implore Thee, O Thou Maker of the heavens and Lord of all names,\nby Thy most effulgent Self and Thy most exalted and all-glorious Remembrance,\nto send down upon Thy loved ones that which will draw them nearer unto Thee, and enable them to hearken unto Thine utterances.\n\nTear asunder with the hand of Thy transcendent power, O my Lord, the veil of vain imaginings,\nthat they who are wholly devoted to Thee may see Thee seated on the throne of Thy majesty,\nand the eyes of such as adore Thy unity may rejoice at the splendors of the glory of Thy face.\nThe doors of hope have been shut against the hearts that long for Thee, O my Lord!\nTheir keys are in Thy hands; open them by the power of Thy might and Thy sovereignty.\nPotent art Thou to do as Thou pleasest.\nThou art, verily, the Almighty, the Beneficent.\x02Praise be to Thee, O Lord my God!\nThou seest and knowest that I have called upon Thy servants to turn nowhere except in the direction of Thy bestowals,\nand have bidden them observe naught save the things Thou didst prescribe in Thy Perspicuous Book,\nthe Book which hath been sent down according to Thine inscrutable decree and irrevocable purpose.\n\nI can utter no word, O my God, unless I be permitted by Thee, and can move in no direction until I obtain Thy sanction.\nIt is Thou, O my God, Who hast called me into being through the power of Thy might, and hast endued me with Thy grace to manifest Thy Cause.\nWherefore I have been subjected to such adversities that my tongue hath been hindered from extolling Thee and from magnifying Thy glory.\n\nAll praise be to Thee, O my God, for the things Thou didst ordain for me through Thy decree and by the power of Thy sovereignty.\nI beseech Thee that thou wilt fortify both myself and them that love me in our love for Thee, and wilt keep us firm in Thy Cause.\nI swear by Thy might!\nO my God!\nThy servant's shame is to be shut out as by a veil from Thee, and his glory is to know Thee.\nArmed with the power of Thy name nothing can ever hurt me, and with Thy love in my heart all the world's afflictions can in no wise alarm me.\n\nSend down, therefore, O my Lord, upon me and upon my loved ones that which will protect us from the\nmischief of those that have repudiated Thy truth and disbelieved in Thy signs.\n\nThou art, verily, the All-Glorious, the Most Bountiful.\x02Magnified be Thy name, O God, the Lord of heaven!\nAttire my head with the crown of martyrdom, even as Thou didst attire my body with the\nornament of tribulation before all that dwell in Thy land.\nGrant, moreover, that they whose hearts yearn over Thee may draw nigh unto the horizon of\nThy grace, above which the Day-Star of Thy beauty sheddeth its radiance.\nOrdain, also, for them what will make them rich enough to dispense with aught else except\nThee, and rid them of all attachment to such as have repudiated Thy signs.\n\nThere is none other God but Thee, the Guardian, the Self-Subsisting.\x02O God and the God of all Names, and the Maker of the heavens!\nI entreat Thee by Thy Name through which He Who is the Dayspring of Thy might and the\nDawning-Place of Thy power hath been manifested, through which every solid thing hath been made to\nflow, and every dead corpse hath been quickened, and every moving spirit confirmed—I entreat\nThee to enable me to rid myself of all attachment to any one but Thee, and to serve Thy Cause,\nand to wish what Thou didst wish through the power of Thy sovereignty, and to perform what is\nthe good pleasure of Thy will.\n\nI beseech Thee, moreover, O my God, to ordain for me what will make me rich enough to dispense with any one save Thee.\nThou seest me, O my God, with my face turned towards Thee, and my hands clinging to the cord of Thy grace.\nSend down upon me Thy mercy, and write down for me what Thou hast written down for Thy chosen ones.\nPowerful art Thou to do what pleaseth Thee.\nNo God is there but Thee, the Ever-Forgiving, the All-Bountiful.\x02From the sweet-scented streams of Thine eternity give me to drink,\nO my God, and of the fruits of the tree of Thy being enable me to taste, O my Hope!\nFrom the crystal springs of Thy love suffer me to quaff, O my Glory,\nand beneath the shadow of Thine everlasting providence let me abide, O my Light!\nWithin the meadows of Thy nearness, before Thy presence, make me able to roam, O my Beloved,\nand at the right hand of the throne of Thy mercy, seat me, O my Desire!\nFrom the fragrant breezes of Thy joy let a breath pass over me, O my Goal,\nand into the heights of the paradise of Thy reality let me gain admission, O my Adored One!\nTo the melodies of the dove of Thy oneness suffer me to hearken, O Resplendent One,\nand through the spirit of Thy power and Thy might quicken me, O my Provider!\nIn the spirit of Thy love keep me steadfast, O my Succorer,\nand in the path of Thy good pleasure set firm my steps, O my Maker!\nWithin the garden of Thine immortality, before Thy countenance, let me abide for ever,\nO Thou Who art merciful unto me, and upon the seat of Thy glory stablish me,\nO Thou Who art my Possessor!\nTo the heaven of Thy loving-kindness lift me up, O my Quickener,\nand unto the Daystar of Thy guidance lead me, O Thou my Attractor!\nBefore the revelations of Thine invisible spirit summon me to be present,\nO Thou Who art my Origin and my Highest Wish, and unto the essence of the fragrance of Thy beauty,\nwhich Thou wilt manifest, cause me to return, O Thou Who art my God!\n\nPotent art Thou to do what pleaseth Thee.\nThou art, verily, the Most Exalted, the All-Glorious, the All-Highest.\x02I\nmagnify Thy Name, O my God, and offer thanksgiving unto Thee, O my Desire, inasmuch as Thou hast\nenabled me to clearly perceive Thy straight Path, hast unveiled Thy Great Announcement before\nmine eyes and hast aided me to set my face towards the Dayspring of Thy Revelation and the\nFountainhead of Thy Cause, whilst Thy servants and Thy people turned away from Thee.\nI entreat Thee, O Lord of the Kingdom of eternity, by the shrill voice of the Pen of Glory,\nand by the Burning Fire which calleth aloud from the verdant Tree, and by the Ark which Thou\nhast specially chosen for the people of Bahá, to grant that I may remain steadfast in\nmy love for Thee, be well pleased with whatsoever Thou hast prescribed for me in Thy Book\nand may stand firm in Thy service and in the service of Thy loved ones.\nGraciously assist then Thy servants, O my God, to do that which will serve to exalt Thy\nCause and will enable them to observe whatsoever Thou hast revealed in Thy Book.\n\nVerily Thou art the Lord of Strength, Thou art potent to ordain whatsoever Thou willest and\nwithin Thy grasp Thou holdest the reins of all created things.\nNo God is there but Thee, the All-Powerful, the All-Knowing, the All-Wise.\x02Magnified be Thy name, O my God,\nfor that Thou hast manifested the Day which is the King of Days,\nthe Day which Thou didst announce unto Thy chosen Ones and Thy Prophets in Thy most excellent Tablets,\nthe Day whereon Thou didst shed the splendor of the glory of all Thy names upon all created things.\nGreat is his blessedness whosoever hath set himself towards Thee,\nand entered Thy presence, and caught the accents of Thy voice.\n\nI beseech Thee, O my Lord, by the name of Him round Whom circleth in adoration the kingdom of Thy names,\nthat Thou wilt graciously assist them that are dear to Thee to glorify Thy word among Thy servants,\nand to shed abroad Thy praise amidst Thy creatures,\nso that the ecstasies of Thy revelation may fill the souls of all the dwellers of Thine earth.\n\nSince Thou hast guided them, O my Lord, unto the living waters of Thy grace, grant,\nby Thy bounty, that they may not be kept back from Thee;\nand since Thou hast summoned them to the habitation of Thy throne,\ndrive them not out from Thy presence, through Thy loving-kindness.\nSend down upon them what shall wholly detach them from aught else except Thee,\nand make them able to soar in the atmosphere of Thy nearness,\nin such wise that neither the ascendancy of the oppressor nor the\nsuggestions of them that have disbelieved in Thy most august and most mighty\nSelf shall be capable of keeping them back from Thee.\x02O\nThou incomparable God!\nO Thou Lord of the Kingdom!\nThese souls are Thy heavenly army.\nAssist them and, with the cohorts of the Supreme Concourse, make them victorious,\nso that each one of them may become like unto a regiment and conquer these countries through the love of\nGod and the illumination of divine teachings.\n\nO God!\nBe Thou their supporter and their helper, and in the wilderness, the mountain, the valley,\nthe forests, the prairies and the seas, be Thou their confidant—so that they may cry out through the power of the\nKingdom and the breath of the Holy Spirit.\n\nVerily, Thou art the Powerful, the Mighty and the Omnipotent, and Thou art the Wise, the Hearing and the Seeing.\x02O\nThou Whose tests are a healing medicine to such as are nigh unto Thee,\nWhose sword is the ardent desire of all them that love Thee,\nWhose dart is the dearest wish of those hearts that yearn after Thee,\nWhose decree is the sole hope of them that have recognized Thy truth!\nI implore Thee, by Thy divine sweetness and by the splendors of the glory of Thy face,\nto send down upon us from Thy retreats on high that which will enable us to draw nigh unto Thee.\nSet, then, our feet firm, O my God, in Thy Cause, and enlighten our hearts with the effulgence of Thy knowledge,\nand illumine our breasts with the brightness of Thy names.\x02Praise be to Thee, O Lord my God!\nI swear by Thy might!\nSuccessive afflictions have withheld the pen of the Most High from laying bare that which is\nhidden from the eyes of Thy creatures, and incessant trials have hindered the tongue of the\nDivine Ordainer from proclaiming the wonders of Thy glorification and praise.\nWith a stammering tongue, therefore, I call upon Thee, O my God, and with this my\nafflicted pen I occupy myself in remembrance of Thy name.\n\nIs there any man of insight, O my God, that can behold Thee with Thine own eye, and where is\nthe thirsty one who can direct his face towards the living waters of Thy love?\nI am the one, O my God, who hath blotted out from his heart the remembrance of all except\nThee, and hath graven upon it the mysteries of Thy love.\nThine own might beareth me witness!\nBut for tribulations, how could the assured be distinguished from the doubters among Thy servants?\nThey who have been inebriated with the wine of Thy knowledge, these, verily, hasten to\nmeet every manner of adversity in their longing to pass into Thy presence.\nI implore Thee, O Beloved of my heart and the Object of my soul's adoration, to shield\nthem that love me from the faintest trace of evil and corrupt desires.\nSupply them, then, with the good of this world and of the next.\n\nThou art, verily, He Whose grace hath guided them aright, He Who hath declared Himself to be the All-Merciful.\nNo God is there but Thee, the All-Glorious, the Supreme Helper.\x02Thou seest, O my God, how Thy loved ones have been encompassed by the\nrebellious amongst Thy creatures and the wicked amidst Thy people.\nNo land remaineth but the lamentation of Thy lovers and the wailing of Thy chosen ones were lifted up therein.\nI beseech Thee by Thy Most Great Name to draw forth the hand of power from the bosom of Thy\nmight and to assist therewith all them that love Thee.\n\nThou beholdest, O my God, their eyes turned towards Thee, their gaze fixed upon the Dayspring of Thy might and Thy loving providence.\nTransmute, O my Lord, their abasement into glory, their poverty into wealth, and their weakness into a strength born of Thee.\n\nPowerful art Thou to do whatsoever Thou willest.\nNo God is there but Thee, the All-Knowing, the All-Informed.\x02O\nmy God!\nO my God!\nUnite the hearts of Thy servants, and reveal to them Thy great purpose.\nMay they follow Thy commandments and abide in Thy law.\nHelp them, O God, in their endeavor, and grant them strength to serve Thee.\nO God!\nLeave them not to themselves, but guide their steps by the light of Thy knowledge, and cheer their hearts by Thy love.\nVerily, Thou art their Helper and their Lord.\x02O\nThou Whose face is the object of the adoration of all that yearn after Thee, Whose presence is\nthe hope of such as are wholly devoted to Thy will, Whose nearness is the desire of all that have\ndrawn nigh unto Thy court, Whose countenance is the companion of those who have recognized Thy\ntruth, Whose name is the mover of the souls that long to behold Thy face, Whose voice is the true\nlife of Thy lovers, the words of Whose mouth are as the waters of life unto all who are in heaven\nand on earth!\n\nI beseech Thee, by the wrong Thou hast suffered and the ills inflicted upon Thee by the hosts\nof wrongful doers, to send down upon me from the clouds of Thy mercy that which will purify me of\nall that is not of Thee, that I may be worthy to praise Thee and fit to love Thee.\n\nWithhold not from me, O my Lord, the things Thou didst ordain for such of Thy handmaidens as\ncircle around Thee, and on whom are poured continually the splendors of the sun of Thy beauty and\nthe beams of the brightness of Thy face.\nThou art He Who from everlasting hath succored whosoever hath sought Thee, and bountifully favored\nhim who hath asked Thee.\n\nNo God is there beside Thee, the Mighty, the Ever-Abiding, the All-Bounteous, the Most Generous.\x02O\nThou kind Lord!\nFrom the horizon of detachment Thou hast manifested souls that, even as the shining moon, shed\nradiance upon the realm of heart and soul, rid themselves from the attributes of the world of\nexistence and hastened forth unto the kingdom of immortality.\nWith a drop from the ocean of Thy loving-kindness Thou didst oft-times moisten the gardens of\ntheir hearts until they gained incomparable freshness and beauty.\nThe holy fragrance of Thy divine unity was diffused far and wide, shedding its sweet savors over\nthe entire world, causing the regions of the earth to be redolent with perfume.\n\nRaise up then, O spirit of Purity, souls who, like those sanctified beings, will become free and\npure, will adorn the world of being with a new raiment and a wondrous robe, will seek no one else\nbut Thee, tread no path except the path of Thy good pleasure and will speak of naught but the\nmysteries of Thy Cause.\n\nO Thou kind Lord!\nGrant that this youth may attain unto that which is the highest aspiration of the holy ones.\nEndow him with the wings of Thy strengthening grace—wings of detachment and divine aid—that\nhe may soar thereby into the atmosphere of Thy tender mercy, be able to partake of Thy celestial\nbestowals, may become a sign of divine guidance and a standard of the Concourse on high.\nThou art the Potent, the Powerful, the Seeing, the Hearing.";

const OCCA_T = "This is, O my God, the first of the days...\x01Magnified art Thou, O Lord...\x01Intercalary Days\x01O God, my God! We are servants of Thine...\x01Tablet of Ahmad";
const OCCA_A = "Bahá'u'lláh\x01Bahá'u'lláh\x01Bahá'u'lláh\x01'Abdu’l-Bahá\x01Bahá'u'lláh";
const OCCA_X = "The _Kitáb-i-Aqdas_ states: “We have commanded you to pray and fast from the beginning of maturity \\[15 years\\];\nthis is ordained by God, your Lord and the Lord of your forefathers...\nThe traveler, the ailing, those who are with child or giving suck, are not bound by the fast...\nAbstain from food and drink from sunrise to sundown, and beware lest desire deprive you of this grace that is appointed in the Book.”\n\nThe period of the Fast is March 2 through March 20.\n\nThis is, O my God, the first of the days on which Thou hast bidden\nThy loved ones to observe the Fast.\nI ask of Thee by Thy Self and by him who hath fasted out of love for Thee and for Thy good-pleasure—and not out of self and desire,\nnor out of fear of Thy wrath—and by Thy most excellent names and august attributes,\nto purify Thy servants from the love of aught except Thee and to draw them nigh unto the Dawning-Place of the lights of\nThy countenance and the Seat of the throne of Thy oneness.\nIllumine their hearts, O my God, with the light of Thy knowledge and brighten their faces with the rays of the\nDaystar that shineth from the horizon of Thy Will.\nPotent art Thou to do what pleaseth Thee.\nNo God is there but Thee, the All-Glorious, Whose help is implored by all men.\n\nAssist them, O my God, to render Thee victorious and to exalt Thy Word.\nSuffer them, then, to become as hands of Thy Cause amongst Thy servants,\nand make them to be revealers of Thy religion and Thy signs amongst mankind,\nin such wise that the whole world may be filled with Thy remembrance and praise and with Thy proofs and evidences.\nThou art, verily, the All-Bounteous, the Most Exalted, the Powerful, the Mighty, and the Merciful.\x02Magnified art Thou, O Lord of the entire creation, the One unto Whom all things must turn.\nWith my inner and outer tongues I bear witness that thou hast manifested and revealed Thyself,\nsent down Thy signs, and proclaimed Thy testimonies.\nI testify to Thy self-sufficiency from aught else except Thee, and Thy sanctity above all earthly things.\nI entreat Thee by the transcendent glory of Thy Cause and the supreme potency of Thy Word to grant\nconfirmation unto him who desireth to offer what Thou hast prescribed unto him in Thy Book and to\nobserve that which will shed forth the fragrance of Thine acceptance.\nVerily Thou art the All-Mighty, the All-Gracious, the All-Forgiving, the All-Generous.\x02My God, my Fire and my Light!\nThe days which Thou hast named the Ayyám-i-Há¹ in Thy Book have begun,\nO Thou Who art the King of names, and the Fast which Thy most exalted Pen hath enjoined unto all who are in the\nkingdom of Thy creation to observe is approaching.\nI entreat Thee, O my Lord, by these days and by all such as have during that period clung to the cord of Thy commandments,\nand laid hold on the handle of Thy precepts, to grant that unto every soul may be assigned a place within the precincts of Thy court,\nand a seat at the revelation of the splendors of the light of Thy countenance.\n\nThese, O my Lord, are Thy servants whom no corrupt inclination hath kept back from what Thou didst send down in Thy Book.\nThey have bowed themselves before Thy Cause, and received Thy Book with such resolve as is born of Thee,\nand observed what Thou hadst prescribed unto them, and chosen to follow that which had been sent down by Thee.\n\nThou seest, O my Lord, how they have recognized and confessed whatsoever Thou hast revealed in Thy Scriptures.\nGive them to drink, O my Lord, from the hands of Thy graciousness the waters of Thine eternity.\nWrite down, then, for them the recompense ordained for him that hath immersed himself in the ocean of Thy presence,\nand attained unto the choice wine of Thy meeting.\n\nI implore Thee, O Thou the King of kings and the Pitier of the downtrodden,\nto ordain for them the good of this world and of the world to come.\nWrite down for them, moreover, what none of Thy creatures hath discovered,\nand number them with those who have circled round Thee, and who move about Thy throne in every world of Thy worlds.\n\nThou, truly, art the Almighty, the All-Knowing, the All-Informed.\x02O\nGod, my God!\nWe are servants of Thine that have turned with devotion to Thy Holy Face,\nthat have detached ourselves from all besides Thee in this glorious Day.\nWe have gathered in this Spiritual Assembly, united in our views and thoughts,\nwith our purposes harmonized to exalt Thy Word amidst mankind.\nO Lord, our God!\nMake us the signs of Thy Divine Guidance, the Standards of Thine exalted Faith amongst men,\nservants to Thy mighty Covenant, O Thou our Lord Most High, manifestations of Thy Divine Unity in Thine Abhá Kingdom,\nand resplendent stars shining upon all regions.\nLord!\nAid us to become seas surging with the billows of Thy wondrous Grace, streams flowing from Thine all-glorious Heights,\ngoodly fruits upon the Tree of Thy heavenly Cause, trees waving through the breezes of Thy Bounty in Thy celestial Vineyard.\nO God!\nMake our souls dependent upon the Verses of Thy Divine Unity, our hearts cheered with the outpourings of Thy Grace,\nthat we may unite even as the waves of one sea and become merged together as the rays of Thine effulgent Light;\nthat our thoughts, our views, our feelings may become as one reality, manifesting the spirit of union throughout the world.\nThou art the Gracious, the Bountiful, the Bestower, the Almighty, the Merciful, the Compassionate.\x02He is the King, the All-Knowing, the Wise!\nLo, the Nightingale of Paradise singeth upon the twigs of the Tree of Eternity, with holy and sweet melodies,\nproclaiming to the sincere ones the glad tidings of the nearness of God,\ncalling the believers in the Divine Unity to the court of the Presence of the Generous One,\ninforming the severed ones of the message which hath been revealed by God, the King, the Glorious,\nthe Peerless, guiding the lovers to the seat of sanctity and to this resplendent Beauty.\n\nVerily this is that Most Great Beauty, foretold in the Books of the Messengers,\nthrough Whom truth shall be distinguished from error and the wisdom of every command shall be tested.\nVerily He is the Tree of Life that bringeth forth the fruits of God, the Exalted, the Powerful, the Great.\n\nO Ahmad!\nBear thou witness that verily He is God and there is no God but Him, the King, the Protector, the Incomparable, the Omnipotent.\nAnd that the One Whom He hath sent forth by the name of ‘Alí¹ was the true One from God, to Whose commands we are all conforming.\n\nSay: O people be obedient to the ordinances of God, which have been enjoined in the Bayán by the Glorious, the Wise One.\nVerily He is the King of the Messengers and His book is the Mother Book did ye but know.\n\nThus doth the Nightingale utter His call unto you from this prison.\nHe hath but to deliver this clear message.\nWhosoever desireth, let him turn aside from this counsel and whosoever desireth let him choose the path to his Lord.\n\nO people, if ye deny these verses, by what proof have ye believed in God?\nProduce it, O assemblage of false ones.\n\nNay, by the One in Whose hand is my soul, they are not, and never shall be able to do this, even should they combine to assist one another.\n\nO Ahmad!\nForget not My bounties while I am absent.\nRemember My days during thy days, and My distress and banishment in this remote prison.\nAnd be thou so steadfast in My love that thy heart shall not waver,\neven if the swords of the enemies rain blows upon thee and all the heavens and the earth arise against thee.\n\nBe thou as a flame of fire to My enemies and a river of life eternal to My loved ones, and be not of those who doubt.\n\nAnd if thou art overtaken by affliction in My path, or degradation for My sake, be not thou troubled thereby.\n\nRely upon God, thy God and the Lord of thy fathers.\nFor the people are wandering in the paths of delusion, bereft of discernment to see God with their own eyes,\nor hear His Melody with their own ears.\nThus have We found them, as thou also dost witness.\n\nThus have their superstitions become veils between them and their own hearts and kept them from the path of God,\nthe Exalted, the Great.\n\nBe thou assured in thyself that verily,\nhe who turns away from this Beauty hath also turned away from the\nMessengers of the past and showeth pride towards God from all eternity to all eternity.\n\nLearn well this Tablet, O Ahmad.\nChant it during thy days and withhold not thyself therefrom.\nFor verily, God hath ordained for the one who chants it, the reward of a hundred martyrs and a service in both worlds.\nThese favors have We bestowed upon thee as a bounty on Our part and a mercy from Our presence, that thou mayest be of those who are grateful.\n\nBy God!\nShould one who is in affliction or grief read this Tablet with absolute sincerity,\nGod will dispel his sadness, solve his difficulties and remove his afflictions.\n\nVerily, He is the Merciful, the Compassionate.\nPraise be to God, the Lord of all the worlds.";

export const CATS = [
    { t: "Obligatory", i: "O", n: 1, T: OBLI_T, A: OBLI_A, X: OBLI_X },
    { t: "General", i: "G", n: 35, T: GENE_T, A: GENE_A, X: GENE_X },
    { t: "Occasional", i: "C", n: 5, T: OCCA_T, A: OCCA_A, X: OCCA_X },
];

export function getPrayer(catIdx, itemIdx) {
    const c = CATS[catIdx];
    return {
        title: c.T.split("\x01")[itemIdx],
        by: c.A.split("\x01")[itemIdx],
        text: c.X.split("\x02")[itemIdx]
    };
}